// Klantenportaal (customer.cohentra.digital). Bevat de bestaande onderdelen (aanmelden, herstel, EventHub-licentiequotum,
// support, wachtwoord) plus de shop: registratie, bestellen, producten en downloads, abonnementen, licenties, facturen en gebruikers.
// Alles draait op dezelfde origin (CSP connect-src 'self'); betalingen lopen via de licentie-worker naar de shop-worker.

export const CUSTOMER_PORTAL_HTML = String.raw`<!doctype html>
<html lang="nl"><head><meta charset="utf-8"><link rel="icon" type="image/png" href="/brand/cohentra-beeldmerk.png"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cohentra | Klantenportaal</title>
<style>
:root{color-scheme:light;--ink:#121e36;--muted:#5f6b78;--line:#dbe3ee;--blue:#2d64d4;--blue-deep:#2252b5;--navy:#121e36;--pale:#f3f6fb;--tint:#eaf0fb;--green:#e5f5ee;--green-ink:#138a66;--red:#be4054;--red-bg:#fdecee;--amber:#fff6e5;--amber-ink:#8a5a00}*{box-sizing:border-box}
body{margin:0;background:#f6f8fc;color:var(--ink);font:15px/1.55 system-ui,-apple-system,"Segoe UI",sans-serif}a{color:var(--blue)}
.top{background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;padding:18px max(20px,calc((100vw - 1080px)/2))}.top p{margin:0;color:var(--muted)}.brand-logo{height:46px;width:auto;display:block}.top-links{display:flex;gap:16px;align-items:center;font-size:14px}.top-links a{text-decoration:none}
.wrap{max-width:1080px;margin:28px auto;padding:0 20px}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:24px;margin:16px 0;box-shadow:0 6px 24px rgba(18,30,54,.05)}.narrow{max-width:480px;margin:40px auto}
h1{font-size:25px;margin:0 0 5px}h2{font-size:19px;margin:0 0 10px}h3{font-size:16px;margin:0 0 6px}.muted{color:var(--muted)}.small{font-size:13px}
label{display:block;font-weight:650;margin:13px 0 5px}input,select,textarea{font:inherit;width:100%;padding:10px 12px;border:1px solid #c8d3e1;border-radius:8px;background:#fff;color:var(--ink)}input:focus,select:focus,textarea:focus{outline:none;border-color:var(--blue);box-shadow:0 0 0 3px rgba(45,100,212,.15)}textarea{min-height:140px;resize:vertical}
button,.btn{font:inherit;border:0;border-radius:8px;padding:10px 15px;background:var(--blue);color:#fff;cursor:pointer;font-weight:650;text-decoration:none;display:inline-block}button:hover,.btn:hover{background:var(--blue-deep)}button:disabled{opacity:.6;cursor:wait}button.secondary,.btn.secondary{background:#e8eef7;color:var(--ink)}button.danger{background:var(--red-bg);color:var(--red)}button.link{background:none;color:var(--blue);padding:0;font-weight:600}
button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid rgba(45,100,212,.45);outline-offset:2px}
.actions{display:flex;gap:10px;align-items:center;margin-top:15px;flex-wrap:wrap}.row{display:grid;grid-template-columns:1fr 1fr;gap:14px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.stat{background:var(--pale);border-radius:10px;padding:15px}.stat strong{display:block;font-size:23px}.stat span{font-size:13px;color:var(--muted)}
.error{color:var(--red);margin-top:9px}.notice{background:var(--green);border:1px solid #c5e6d6;border-radius:10px;padding:13px 15px;margin:12px 0;overflow-wrap:anywhere}.notice.info{background:var(--tint);border-color:#cddcf5}.notice.warn{background:var(--amber);border-color:#f1dcae;color:var(--amber-ink)}.notice.error{background:var(--red-bg);border-color:#f3c6cd;color:#8c2537}
.hidden{display:none!important}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:600px}th,td{text-align:left;padding:11px 8px;border-bottom:1px solid var(--line);vertical-align:top}th{color:var(--muted);font-size:13px;font-weight:600}.key{font:700 16px ui-monospace,monospace;word-break:break-all}.split{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}
.tabs{display:flex;gap:4px;overflow-x:auto;border-bottom:1px solid var(--line);margin:8px 0 0;scrollbar-width:thin}.tabs button{background:none;color:var(--muted);border-radius:0;border-bottom:3px solid transparent;padding:12px 14px;white-space:nowrap;font-weight:600}.tabs button[aria-selected=true]{color:var(--ink);border-bottom-color:var(--blue)}
.pill{display:inline-flex;align-items:center;gap:6px;border-radius:99px;padding:3px 10px;font-size:12px;font-weight:700;background:var(--pale);color:var(--muted)}.pill.ok{background:var(--green);color:var(--green-ink)}.pill.warn{background:var(--amber);color:var(--amber-ink)}.pill.bad{background:var(--red-bg);color:var(--red)}
.items{display:grid;gap:12px}.items>*,.item{min-width:0}.item{border:1px solid var(--line);border-radius:12px;padding:16px}.item-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;flex-wrap:wrap}.features{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0 0;padding:0;list-style:none}.features li{background:var(--tint);color:#1d3f86;border-radius:99px;padding:3px 10px;font-size:13px}
.choice{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:6px}.choice label{margin:0;border:1px solid var(--line);border-radius:10px;padding:12px;font-weight:600;cursor:pointer;display:flex;gap:10px;align-items:flex-start}.choice input{width:auto;margin-top:3px}.choice small{display:block;font-weight:400;color:var(--muted)}.choice label:has(input:checked){border-color:var(--blue);background:var(--tint)}
.empty{padding:22px;text-align:center;color:var(--muted);border:1px dashed var(--line);border-radius:12px}.loading{color:var(--muted)}
@media(max-width:650px){.wrap{margin:16px auto;padding:0 16px}.row,.grid,.choice{grid-template-columns:1fr}.card{padding:18px}.top{padding:14px 16px}.brand-logo{height:36px}}
</style></head><body><header class="top"><img class="brand-logo" src="/brand/cohentra-logo.png" width="126" height="46" alt="Cohentra Digital"><div class="top-links"><a href="https://cohentra.digital/shop">Shop</a><p>Klantenportaal</p></div></header><main class="wrap">

<section id="login" class="card narrow hidden"><h1>Aanmelden</h1><p class="muted">Beheer je producten, abonnementen en licenties op één plek.</p><div id="buyHint" class="notice info hidden"></div><form id="loginForm"><label for="username">E-mailadres of gebruikersnaam</label><input id="username" autocomplete="username" required><label for="password">Wachtwoord</label><input id="password" type="password" autocomplete="current-password" required><div class="actions"><button id="loginButton">Aanmelden</button><button id="forgotButton" type="button" class="secondary">Wachtwoord vergeten?</button></div><div id="loginError" class="error" role="alert"></div></form><p class="muted">Nog geen account? <button type="button" class="link" id="toRegister">Account aanmaken</button></p><p class="muted small">Hulp nodig bij aanmelden? <a href="mailto:info@cohentra.digital?subject=Hulp%20bij%20aanmelden">Mail Cohentra</a>.</p></section>

<section id="registerPanel" class="card narrow hidden"><h1>Account aanmaken</h1><p class="muted">Met een account bestel je producten en beheer je abonnementen, licenties en downloads.</p><form id="registerForm" novalidate><fieldset style="border:0;padding:0;margin:0"><legend style="font-weight:650;margin:6px 0 0">Ik maak een account aan als</legend><div class="choice"><label><input type="radio" name="customerType" value="individual" checked><span>Particulier of zelfstandige<small>Ook voor eenmanszaken en zzp'ers. Zakelijke factuurgegevens kun je bij het bestellen opgeven.</small></span></label><label><input type="radio" name="customerType" value="business"><span>Organisatie<small>Voor bedrijven met meerdere gebruikers. Jij wordt beheerder.</small></span></label></div></fieldset><div id="companyBox" class="hidden"><label for="regCompany">Naam organisatie</label><input id="regCompany" maxlength="120" autocomplete="organization"></div><label for="regName">Je naam</label><input id="regName" maxlength="120" autocomplete="name" required><label for="regEmail">E-mailadres</label><input id="regEmail" type="email" maxlength="254" autocomplete="email" required><label for="regPassword">Wachtwoord</label><input id="regPassword" type="password" minlength="10" autocomplete="new-password" required><p class="muted small">Minimaal 10 tekens. We sturen een e-mail om je adres te bevestigen; daarna is je account actief.</p><p class="muted small">We gebruiken je gegevens voor je account, bestellingen en ondersteuning. Vragen over privacy? Mail <a href="mailto:info@cohentra.digital">info@cohentra.digital</a>.</p><div class="actions"><button id="registerButton">Account aanmaken</button><button type="button" class="secondary" id="registerBack">Terug</button></div><div id="registerMessage" role="status"></div></form></section>

<section id="verifyPanel" class="card narrow hidden"><h1>E-mailadres bevestigen</h1><p id="verifyMessage" class="muted" role="status">Even geduld, je account wordt geactiveerd…</p><div class="actions hidden" id="verifyActions"><button type="button" id="verifyToLogin">Naar aanmelden</button></div></section>

<section id="forgotPanel" class="card narrow hidden"><h1>Wachtwoord herstellen</h1><p class="muted">Vul het e-mailadres in dat bij je klantaccount hoort. Als er een account is, sturen we een beveiligde link.</p><form id="forgotForm"><label for="forgotEmail">E-mailadres</label><input id="forgotEmail" type="email" autocomplete="email" required><div class="actions"><button id="forgotSubmit">Herstellink sturen</button><button type="button" id="backToLogin" class="secondary">Terug</button></div><div id="forgotMessage" role="status"></div></form></section>

<section id="tokenPanel" class="card narrow hidden"><h1 id="tokenTitle">Wachtwoord instellen</h1><p class="muted">Kies een wachtwoord voor je klantenportaalaccount.</p><form id="tokenForm"><label for="tokenPassword">Nieuw wachtwoord</label><input id="tokenPassword" type="password" autocomplete="new-password" required><label for="tokenPasswordConfirm">Herhaal wachtwoord</label><input id="tokenPasswordConfirm" type="password" autocomplete="new-password" required><div class="actions"><button id="tokenSubmit">Wachtwoord opslaan</button></div><div id="tokenMessage" class="error" role="alert"></div></form></section>

<div id="dashboard" class="hidden"><section class="card" style="padding-bottom:0"><div class="split"><div><h1 id="welcome">Klantenportaal</h1><p class="muted" id="welcomeSub"></p></div><button class="secondary" id="logout">Afmelden</button></div><div id="notices" aria-live="polite"></div><nav class="tabs" role="tablist" aria-label="Onderdelen" id="tabs"></nav></section>

<section id="tab-checkout" class="card tab hidden"><h2>Bestelling controleren</h2><div id="checkoutBody" class="loading">Laden…</div></section>

<section id="tab-return" class="card tab hidden"><h2>Betaling</h2><div id="returnBody" role="status"></div></section>

<section id="tab-products" class="card tab hidden"><div class="split"><h2>Mijn producten en downloads</h2><a class="btn secondary" href="https://cohentra.digital/shop">Naar de shop</a></div><div id="productsBody" class="loading">Laden…</div></section>

<section id="tab-subscriptions" class="card tab hidden"><div class="split"><h2>Abonnementen</h2><button class="secondary hidden" id="portalButton" type="button">Betaalgegevens beheren</button></div><p class="muted small" id="portalHint"></p><div id="subscriptionsBody" class="loading">Laden…</div></section>

<section id="tab-licenses" class="card tab hidden"><h2>Licenties en activaties</h2><p class="muted small" id="shopLicenseIntro">Elke licentiesleutel werkt op één apparaat. Het abonnement bepaalt hoeveel sleutels je kunt aanmaken en welke functies werken. Volledige sleutels worden alleen direct na het aanmaken getoond.</p><div id="newKey" class="notice hidden"><strong>Bewaar deze sleutel; hij wordt hierna niet opnieuw getoond.</strong><p class="key" id="newKeyValue"></p><button type="button" class="secondary" id="copyNewKey">Kopieer sleutel</button></div><div id="licensesBody" class="loading">Laden…</div>
<div id="legacyBox" class="hidden"><h2 style="margin-top:28px">EventHub-licenties via Cohentra</h2><p class="muted small">Licenties uit het quotum dat Cohentra voor jullie heeft ingesteld.</p><div class="grid"><div class="stat"><strong id="used">—</strong><span>Licenties in gebruik</span></div><div class="stat"><strong id="limit">—</strong><span>Maximaal toegestaan</span></div><div class="stat"><strong id="types">—</strong><span>Toegestane typen</span></div></div><form id="createForm" class="hidden"><div class="row"><div><label for="label">Naam / gebruiker (optioneel)</label><input id="label" maxlength="80" placeholder="Bijvoorbeeld Testgebruiker"></div><div><label for="type">Licentietype</label><select id="type"></select></div></div><div class="row" id="dates"><div><label for="validFrom">Geldig vanaf</label><input id="validFrom" type="date" required></div><div><label for="validUntil">Geldig tot en met</label><input id="validUntil" type="date" required></div></div><div class="actions"><button id="createButton">Licentie aanmaken</button></div><div id="createError" class="error" role="alert"></div><div id="createdKey" class="notice hidden"><strong>Bewaar deze sleutel; hij wordt hierna niet opnieuw getoond.</strong><p class="key" id="keyValue"></p><button type="button" class="secondary" id="copyKey">Kopieer sleutel</button></div></form><div class="table-wrap"><table><thead><tr><th>Naam</th><th>Type</th><th>Geldig vanaf</th><th>Geldig tot</th><th>Status</th><th></th></tr></thead><tbody id="licenses"></tbody></table></div></div></section>

<section id="tab-billing" class="card tab hidden"><h2>Bestellingen en facturen</h2><p class="muted small">Facturen worden door Stripe opgemaakt en verstuurd. Je vindt ze hier terug.</p><div id="billingBody" class="loading">Laden…</div></section>

<section id="tab-account" class="card tab hidden"><h2>Account en factuurgegevens</h2><div id="accountBody"></div><h2 style="margin-top:28px">Wachtwoord wijzigen</h2><form id="passwordForm"><div class="row"><div><label for="oldPassword">Huidig wachtwoord</label><input id="oldPassword" type="password" autocomplete="current-password" required></div><div><label for="newPassword">Nieuw wachtwoord</label><input id="newPassword" type="password" autocomplete="new-password" required></div></div><div class="actions"><button class="secondary">Wachtwoord wijzigen</button></div><div id="passwordMessage" class="error" role="status"></div></form></section>

<section id="tab-team" class="card tab hidden"><h2>Gebruikers</h2><p class="muted small" id="teamHint"></p><div id="teamBody" class="loading">Laden…</div><form id="teamForm" class="hidden"><h3 style="margin-top:20px">Gebruiker uitnodigen</h3><div class="row"><div><label for="teamName">Naam</label><input id="teamName" maxlength="120" required></div><div><label for="teamEmail">E-mailadres</label><input id="teamEmail" type="email" maxlength="254" required></div></div><p class="muted small">Nieuwe gebruikers kunnen producten gebruiken en downloaden. Facturatie, abonnementen en gebruikers beheren kan alleen een beheerder.</p><div class="actions"><button id="teamButton">Uitnodiging sturen</button></div><div id="teamMessage" role="status"></div></form></section>

<section id="tab-support" class="card tab hidden"><h2>Supportaanvraag indienen</h2><p class="muted">Omschrijf je vraag. Stuur geen wachtwoorden of volledige licentiesleutels mee.</p><form id="ticketForm"><div class="row"><div><label for="ticketCategory">Onderwerp</label><select id="ticketCategory"><option value="eventhub">EventHub gebruiken</option><option value="license">Licentie</option><option value="account">Account / toegang</option><option value="other">Anders</option></select></div><div><label for="ticketSubject">Korte omschrijving</label><input id="ticketSubject" maxlength="120" required></div></div><label for="ticketMessage">Waar kunnen we mee helpen?</label><textarea id="ticketMessage" maxlength="6000" required></textarea><div class="actions"><button id="ticketButton">Supportaanvraag versturen</button></div><div id="ticketError" class="error" role="alert"></div><div id="ticketCreated" class="notice hidden" role="status"></div></form><h2 style="margin-top:24px">Mijn supportaanvragen</h2><div class="table-wrap"><table><thead><tr><th>Referentienummer</th><th>Onderwerp</th><th>Datum</th><th>Status</th></tr></thead><tbody id="myTickets"><tr><td colspan="4" class="muted">Laden…</td></tr></tbody></table></div><p class="muted">Liever e-mailen? <a href="mailto:support@cohentra.digital?subject=Supportverzoek">support@cohentra.digital</a></p></section>
</div></main>
<script>
const $=id=>document.getElementById(id);
let token=sessionStorage.getItem('cohentra-customer-token')||'',me={},shop=null,currentTab='products';
const params=new URL(location.href).searchParams;
function safe(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function store(key,value){try{if(value===null)localStorage.removeItem(key);else localStorage.setItem(key,value)}catch{}}
function stored(key){try{return localStorage.getItem(key)}catch{return null}}
function money(amount,currency){if(amount===null||amount===undefined)return '—';try{return new Intl.NumberFormat('nl-NL',{style:'currency',currency:String(currency||'').toUpperCase()}).format(amount/100)}catch{return (amount/100).toFixed(2)+' '+String(currency||'').toUpperCase()}}
function period(p){if(!p||!p.interval)return 'eenmalig';const n=Number(p.interval_count||1),names={day:['dag','dagen'],week:['week','weken'],month:['maand','maanden'],year:['jaar','jaar']}[p.interval]||[p.interval,p.interval];return n===1?'per '+names[0]:'per '+n+' '+names[1]}
function day(v){return v?new Date(v).toLocaleDateString('nl-NL',{day:'numeric',month:'long',year:'numeric'}):'—'}
function pill(text,kind){return '<span class="pill '+(kind||'')+'">'+safe(text)+'</span>'}
function entKind(s){return s==='active'?'ok':s==='grace'||s==='pending'?'warn':'bad'}
function subKind(s){return s==='active'||s==='trialing'?'ok':s==='past_due'||s==='pending'?'warn':'bad'}
function featureList(features,catalog){const keys=Object.keys(features||{});if(!keys.length)return '';return '<ul class="features">'+keys.map(k=>{const f=(catalog||[]).find(x=>x.key===k),name=f?f.name:k,v=features[k];return '<li>'+safe(name)+(v===true?'':': '+safe(v==='unlimited'?'onbeperkt':v))+'</li>'}).join('')+'</ul>'}
function headers(){return {'Authorization':'Bearer '+token,'Content-Type':'application/json'}}
async function api(path,options={}){const r=await fetch(path,{...options,headers:{...headers(),...(options.headers||{})}});let d={};try{d=await r.json()}catch{}if(r.status===401&&token){token='';sessionStorage.removeItem('cohentra-customer-token');showPanel('login');$('loginError').textContent='Je sessie is verlopen. Meld opnieuw aan.'}if(!r.ok){const e=Error(d.error||'De aanvraag is mislukt.');e.status=r.status;e.code=d.code;throw e}return d}
async function publicPost(path,body){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.error||'Het is niet gelukt.');return d}
function showPanel(id){['login','registerPanel','verifyPanel','forgotPanel','tokenPanel','dashboard'].forEach(p=>$(p).classList.toggle('hidden',p!==id));if(id==='login')buyHint()}
function buyHint(){const b=stored('cohentra-buy');$('buyHint').classList.toggle('hidden',!b);$('buyHint').textContent=b?'Meld je aan of maak een account aan om je bestelling af te ronden.':''}
function busy(button,on){if(button)button.disabled=on}

const TABS=[['products','Mijn producten'],['subscriptions','Abonnementen'],['licenses','Licenties'],['billing','Bestellingen en facturen'],['account','Account'],['team','Gebruikers'],['support','Support']];
function visibleTabs(){const admin=me.role==='admin';return TABS.filter(([k])=>{if(k==='billing')return admin;if(k==='team')return admin&&me.customer_type==='business';if(k==='subscriptions'||k==='products')return !!shop;return true})}
function renderTabs(){$('tabs').innerHTML=visibleTabs().map(([k,n])=>'<button type="button" role="tab" data-tab="'+k+'" aria-selected="'+(k===currentTab)+'">'+safe(n)+'</button>').join('')}
function setTab(tab){currentTab=tab;document.querySelectorAll('.tab').forEach(s=>s.classList.toggle('hidden',s.id!=='tab-'+tab));renderTabs()}
$('tabs').onclick=e=>{const t=e.target.closest('[data-tab]');if(t){setTab(t.dataset.tab);history.replaceState({},'',location.pathname+'?tab='+t.dataset.tab)}};

async function load(){
  const meData=await api('/api/customer/me');me=meData.customer;
  $('welcome').textContent='Welkom, '+me.name;
  $('welcomeSub').textContent=(me.customer_type==='business'?'Organisatieaccount':'Particulier / zelfstandig')+' · '+(me.role==='admin'?'beheerder':'gebruiker');
  try{shop=await api('/api/customer/shop/summary')}catch(e){shop=null;if(e.status!==503)console.warn(e.message)}
  showPanel('dashboard');
  renderNotices();renderProducts();renderSubscriptions();renderLicenses();renderBilling();renderAccount();
  if(me.legacy_licensing)await loadLegacy();else $('legacyBox').classList.add('hidden');
  await loadTickets();
  if(me.role==='admin'&&me.customer_type==='business')loadTeam().catch(e=>$('teamBody').textContent=e.message);
  const pendingBuy=stored('cohentra-buy');
  if(params.get('checkout'))return showReturn();
  if(pendingBuy)return openCheckout(pendingBuy);
  const wanted=params.get('tab');setTab(visibleTabs().some(([k])=>k===wanted)?wanted:(shop&&(shop.entitlements.length||!me.legacy_licensing)?'products':'licenses'));
}
function renderNotices(){const list=(shop&&shop.notices)||[];$('notices').innerHTML=list.map(n=>'<div class="notice '+safe(n.level)+'">'+safe(n.text)+'</div>').join('')}

function maatwerkItem(){return me.legacy_licensing?'<div class="item"><div class="item-head"><div><h3>EventHub</h3><p class="muted small" style="margin:0">Maatwerk, geleverd en beheerd door Cohentra.</p></div>'+pill('Actief','ok')+'</div><p class="small">Je EventHub-licenties maak en beheer je onder Licenties, binnen het quotum dat Cohentra voor jullie heeft ingesteld.</p><div class="actions"><button type="button" class="secondary" data-goto-tab="licenses">Naar licenties</button></div></div>':''}
function renderProducts(){if(!shop)return;const ents=shop.entitlements;if(!ents.length){$('productsBody').innerHTML=me.legacy_licensing?'<div class="items">'+maatwerkItem()+'</div>':'<div class="empty">Je hebt nog geen producten. <a href="https://cohentra.digital/shop">Bekijk de shop</a>.</div>';return}
  $('productsBody').innerHTML='<div class="items">'+maatwerkItem()+ents.map(e=>{const rel=shop.releases.filter(r=>r.product_id===e.product_id);let dl='';
    if(!e.download_allowed)dl='<p class="muted small">'+(e.use_allowed?'Downloaden is tijdelijk niet mogelijk zolang de betaling niet in orde is. Bestaande installaties blijven werken.':'Geen downloadrecht: '+safe(e.reason||e.status_label)+'.')+'</p>';
    else if(!rel.length)dl='<p class="muted small">Er is nog geen downloadbestand beschikbaar.</p>';
    else dl='<div class="table-wrap"><table style="min-width:0"><thead><tr><th>Versie</th><th>Platform</th><th>Datum</th><th></th></tr></thead><tbody>'+rel.map(r=>'<tr><td><strong>'+safe(r.version)+'</strong>'+(r.notes?'<details><summary class="small">Versienotities</summary><p class="small" style="white-space:pre-wrap">'+safe(r.notes)+'</p></details>':'')+'</td><td>'+safe(r.platform||'—')+'</td><td>'+safe(day(r.published_at))+'</td><td><button type="button" class="secondary" data-download="'+safe(r.id)+'">Downloaden'+(r.file_size?' ('+(r.file_size/1048576).toFixed(1)+' MB)':'')+'</button></td></tr>').join('')+'</tbody></table></div>';
    return '<div class="item"><div class="item-head"><div><h3>'+safe(e.product_name)+' · '+safe(e.plan_name)+'</h3><p class="muted small" style="margin:0">'+(e.valid_until?(e.use_allowed?'Toegang tot en met ':'Verlopen op ')+safe(day(e.valid_until)):'Geen einddatum')+(e.reason?' · '+safe(e.reason):'')+'</p></div>'+pill(e.status_label,entKind(e.status))+'</div>'+featureList(e.features,shop.feature_names[e.product_id])+dl+'</div>'}).join('')+'</div>'}
$('productsBody').onclick=async e=>{const go=e.target.closest('[data-goto-tab]');if(go){setTab(go.dataset.gotoTab);return}const b=e.target.closest('[data-download]');if(!b)return;busy(b,true);try{const d=await api('/api/customer/downloads/'+encodeURIComponent(b.dataset.download),{method:'POST',body:'{}'});location.href=d.url}catch(err){alert(err.message)}finally{busy(b,false)}};

function renderSubscriptions(){if(!shop)return;const admin=me.role==='admin';$('portalButton').classList.toggle('hidden',!shop.customer.billing_portal_available);$('portalHint').textContent=shop.customer.billing_portal_available?'Via Betaalgegevens beheren (Stripe) wijzig je je betaalmethode en download je eerdere facturen.':'';
  if(!shop.subscriptions.length){$('subscriptionsBody').innerHTML='<div class="empty">Je hebt geen abonnementen.</div>';return}
  $('subscriptionsBody').innerHTML='<div class="items">'+shop.subscriptions.map(s=>{let h='<div class="item" data-sub="'+safe(s.id)+'"><div class="item-head"><div><h3>'+safe(s.product_name)+' · '+safe(s.plan_name)+'</h3><p class="muted small" style="margin:0">'+(s.price?safe(money(s.price.unit_amount,s.price.currency)+' '+period(s.price)):'')+'</p></div>'+pill(s.status_label,subKind(s.status))+'</div>';
    if(s.status==='trialing'&&s.trial_end)h+='<p class="small">Proefperiode tot en met '+safe(day(s.trial_end))+'. Daarna start de betaalde periode, tenzij je opzegt.</p>';
    if(['active','trialing','past_due'].includes(s.status))h+='<p class="small">'+(s.cancel_at_period_end?'Opgezegd. Je houdt toegang tot en met <strong>'+safe(day(s.current_period_end))+'</strong>; daarna stopt het abonnement en werken de licenties niet meer.':'Volgende verlenging: <strong>'+safe(day(s.current_period_end))+'</strong>.')+'</p>';
    if(s.status==='past_due')h+='<p class="small">De laatste betaling is mislukt. Stripe probeert het automatisch opnieuw. Werk je betaalmethode bij via Betaalgegevens beheren.</p>';
    if(['canceled','expired'].includes(s.status))h+='<p class="small">Beëindigd op '+safe(day(s.ended_at||s.current_period_end))+'.</p>';
    if(s.pending)h+='<div class="notice info small">Gepland: overstap naar <strong>'+safe(s.pending.plan_name)+'</strong> per '+safe(day(s.pending.at))+'.'+(admin?' <button type="button" class="link" data-sub-action="cancel-change">Wijziging annuleren</button>':'')+'</div>';
    if(admin&&['active','trialing','past_due'].includes(s.status)){h+='<div class="actions">';if(s.change_options.length)h+='<select data-change-select aria-label="Ander abonnement kiezen" style="max-width:320px"><option value="">Abonnement wijzigen…</option>'+s.change_options.map(o=>'<option value="'+safe(o.price_id)+'">'+safe(o.plan_name+' · '+money(o.unit_amount,o.currency)+' '+period(o))+'</option>').join('')+'</select>';h+=s.cancel_at_period_end?'<button type="button" class="secondary" data-sub-action="resume">Opzegging intrekken</button>':'<button type="button" class="danger" data-sub-action="cancel">Opzeggen</button>';h+='</div><div data-sub-panel></div>'}
    return h+'</div>'}).join('')+'</div>'}
$('subscriptionsBody').onchange=async e=>{const sel=e.target.closest('[data-change-select]');if(!sel||!sel.value)return;const card=sel.closest('[data-sub]'),panel=card.querySelector('[data-sub-panel]');panel.innerHTML='<p class="loading small">Gevolgen berekenen…</p>';
  try{const p=await api('/api/customer/subscriptions/'+card.dataset.sub+'/change-preview',{method:'POST',body:JSON.stringify({price_id:sel.value})});const label=sel.options[sel.selectedIndex].text;
    const text=p.timing==='period_end'?'De overstap naar <strong>'+safe(label)+'</strong> gaat in op <strong>'+safe(day(p.effective_at))+'</strong>, aan het einde van je huidige betaalperiode. Tot die datum houd je je huidige functies. Er volgt geen terugbetaling.':'De overstap naar <strong>'+safe(label)+'</strong> gaat <strong>direct</strong> in. '+(p.amount_due!==null&&p.amount_due!==undefined?'Je betaalt nu '+safe(money(p.amount_due,p.currency))+' (het verschil naar rato voor de rest van deze periode).':'Het prijsverschil voor de rest van deze periode wordt naar rato verrekend.')+' Lukt de betaling niet, dan blijft je huidige abonnement ongewijzigd.';
    panel.innerHTML='<div class="notice info small">'+text+'<div class="actions"><button type="button" data-confirm-change="'+safe(sel.value)+'">Bevestigen</button><button type="button" class="secondary" data-cancel-panel>Annuleren</button></div></div>'}catch(err){panel.innerHTML='<p class="error">'+safe(err.message)+'</p>'}};
$('subscriptionsBody').onclick=async e=>{const card=e.target.closest('[data-sub]');if(!card)return;const id=card.dataset.sub,panel=card.querySelector('[data-sub-panel]');
  if(e.target.closest('[data-cancel-panel]')){panel.innerHTML='';card.querySelector('[data-change-select]').value='';return}
  const confirmChange=e.target.closest('[data-confirm-change]');const act=e.target.closest('[data-sub-action]');
  if(act&&act.dataset.subAction==='cancel'&&panel&&!act.dataset.confirmed){const s=shop.subscriptions.find(x=>x.id===id);panel.innerHTML='<div class="notice warn small">Weet je het zeker? Je houdt toegang tot en met <strong>'+safe(day(s.current_period_end))+'</strong>. Daarna stoppen de licenties en downloads voor dit product. Er volgt geen terugbetaling voor de lopende periode. Tot die datum kun je de opzegging intrekken.<div class="actions"><button type="button" class="danger" data-sub-action="cancel" data-confirmed="1">Ja, opzeggen</button><button type="button" class="secondary" data-cancel-panel>Nee</button></div></div>';return}
  const button=confirmChange||act;if(!button)return;busy(button,true);
  try{if(confirmChange){const d=await api('/api/customer/subscriptions/'+id+'/change',{method:'POST',body:JSON.stringify({price_id:confirmChange.dataset.confirmChange})});alert(d.timing==='period_end'?'De wijziging is gepland per '+day(d.effective_at)+'.':d.applied?'Je abonnement is gewijzigd.':'De wijziging wacht op betaling. Zodra de betaling is gelukt, gaat hij in.')}
    else await api('/api/customer/subscriptions/'+id+'/'+act.dataset.subAction,{method:'POST',body:'{}'});
    await refreshShop()}catch(err){alert(err.message)}finally{busy(button,false)}};
$('portalButton').onclick=async()=>{busy($('portalButton'),true);try{const d=await api('/api/customer/billing-portal',{method:'POST',body:'{}'});location.href=d.url}catch(err){alert(err.message)}finally{busy($('portalButton'),false)}};

function renderLicenses(){if(!shop){$('licensesBody').innerHTML='';$('shopLicenseIntro').classList.toggle('hidden',!!me.legacy_licensing);return}const admin=me.role==='admin',ents=shop.entitlements.filter(e=>e.source);$('shopLicenseIntro').classList.toggle('hidden',!ents.length&&me.legacy_licensing);if(!ents.length){$('licensesBody').innerHTML=me.legacy_licensing?'':'<div class="empty">Er zijn nog geen licenties bij je producten.</div>';return}
  $('licensesBody').innerHTML='<div class="items">'+ents.map(e=>{const lic=shop.licenses.filter(l=>l.entitlement_id===e.id),max=e.max_activations,full=max!==null&&max!==undefined&&e.licenses_in_use>=max;
    let h='<div class="item"><div class="item-head"><div><h3>'+safe(e.product_name)+' · '+safe(e.plan_name)+'</h3><p class="muted small" style="margin:0">'+safe(e.licenses_in_use)+' van '+safe(max===null||max===undefined?'onbeperkt':max)+' activaties in gebruik'+(e.max_users?' · maximaal '+safe(e.max_users)+' gebruikers':'')+'</p></div>'+pill(e.use_allowed?'Mag gebruikt worden':'Niet bruikbaar',e.use_allowed?'ok':'bad')+'</div>';
    if(!e.use_allowed)h+='<p class="small error">Licenties voor dit product werken niet: '+safe(e.reason||e.status_label)+'.</p>';
    if(lic.length)h+='<div class="table-wrap"><table style="min-width:520px"><thead><tr><th>Naam</th><th>Status</th><th>Laatst gezien</th><th></th></tr></thead><tbody>'+lic.map(l=>'<tr><td>'+safe(l.label||'—')+'</td><td>'+safe(l.status)+(l.activated_at?'<br><span class="muted small">sinds '+safe(day(l.activated_at))+'</span>':'')+'</td><td>'+safe(l.last_seen_at?day(l.last_seen_at):'—')+'</td><td>'+(admin&&!l.revoked_at?(l.activated_at?'<button type="button" class="link" data-lic="reset" data-id="'+safe(l.id)+'">Apparaat vrijgeven</button> · ':'')+'<button type="button" class="link" data-lic="revoke" data-id="'+safe(l.id)+'" style="color:var(--red)">Intrekken</button>':'')+'</td></tr>').join('')+'</tbody></table></div>';
    if(admin&&e.use_allowed)h+=full?'<p class="muted small">Het maximale aantal activaties is bereikt. Trek een licentie in om een nieuwe te maken.</p>':'<form class="actions" data-new-license="'+safe(e.id)+'"><input name="label" maxlength="80" placeholder="Naam of apparaat (optioneel)" style="max-width:300px" aria-label="Naam van de licentie"><button>Licentiesleutel maken</button></form>';
    return h+'</div>'}).join('')+'</div>'}
$('licensesBody').onsubmit=async e=>{const f=e.target.closest('[data-new-license]');if(!f)return;e.preventDefault();const b=f.querySelector('button');busy(b,true);try{const d=await api('/api/customer/entitlements/'+f.dataset.newLicense+'/licenses',{method:'POST',body:JSON.stringify({label:f.label.value.trim()})});$('newKeyValue').textContent=d.license.license_key;$('newKey').classList.remove('hidden');$('copyNewKey').onclick=()=>navigator.clipboard.writeText(d.license.license_key);await refreshShop();$('newKey').scrollIntoView({behavior:'smooth',block:'center'})}catch(err){alert(err.message)}finally{busy(b,false)}};
$('licensesBody').onclick=async e=>{const b=e.target.closest('[data-lic]');if(!b)return;const msg=b.dataset.lic==='revoke'?'Deze licentie intrekken? Hij werkt daarna niet meer.':'Het apparaat vrijgeven? De sleutel kan daarna op een ander apparaat worden geactiveerd.';if(!confirm(msg))return;busy(b,true);try{await api('/api/customer/shop-licenses/'+b.dataset.id+'/'+b.dataset.lic,{method:'POST',body:'{}'});await refreshShop()}catch(err){alert(err.message)}finally{busy(b,false)}};

const ORDER_STATUS={processing:['Betaling wordt verwerkt','warn'],paid:['Betaald','ok'],failed:['Mislukt','bad'],expired:['Niet afgerond',''],canceled:['Geannuleerd',''],refunded:['Terugbetaald','bad'],partially_refunded:['Deels terugbetaald','warn']};
const INVOICE_STATUS={open:['Open','warn'],paid:['Betaald','ok'],void:['Vervallen',''],uncollectible:['Oninbaar','bad']};
function renderBilling(){if(!shop||me.role!=='admin')return;let h='<h3>Bestellingen</h3>';h+=shop.orders.length?'<div class="table-wrap"><table><thead><tr><th>Bestelling</th><th>Product</th><th>Datum</th><th>Bedrag</th><th>Status</th></tr></thead><tbody>'+shop.orders.map(o=>{const st=ORDER_STATUS[o.status]||[o.status,''];return '<tr><td><strong>'+safe(o.order_number)+'</strong><br><span class="muted small">'+(o.purchase_context==='business'?'Zakelijk':'Privé')+'</span></td><td>'+safe(o.product_name+' · '+(o.plan_name||''))+'</td><td>'+safe(day(o.created_at))+'</td><td>'+safe(money(o.amount_total,o.currency))+(o.amount_refunded?'<br><span class="muted small">'+safe(money(o.amount_refunded,o.currency))+' terug</span>':'')+'</td><td>'+pill(st[0],st[1])+'</td></tr>'}).join('')+'</tbody></table></div>':'<div class="empty">Nog geen bestellingen.</div>';
  h+='<h3 style="margin-top:22px">Facturen</h3>'+(shop.invoices.length?'<div class="table-wrap"><table><thead><tr><th>Factuur</th><th>Datum</th><th>Bedrag</th><th>Status</th><th></th></tr></thead><tbody>'+shop.invoices.map(i=>{const st=INVOICE_STATUS[i.status]||[i.status,''];return '<tr><td>'+safe(i.number||'—')+'</td><td>'+safe(day(i.stripe_created*1000))+'</td><td>'+safe(money(i.amount_due,i.currency))+'</td><td>'+pill(st[0],st[1])+'</td><td>'+(i.hosted_invoice_url?'<a href="'+safe(i.hosted_invoice_url)+'" target="_blank" rel="noopener">'+(i.status==='open'?'Betalen':'Bekijken')+'</a>':'')+(i.invoice_pdf?' · <a href="'+safe(i.invoice_pdf)+'" target="_blank" rel="noopener">PDF</a>':'')+'</td></tr>'}).join('')+'</tbody></table></div>':'<div class="empty">Nog geen facturen.</div>');
  $('billingBody').innerHTML=h}

function billingFields(c,context){const company=me.customer_type==='business';return (company?'<p class="small muted">Factuur op naam van <strong>'+safe(c.name)+'</strong>.</p>':'<div data-business-only'+(context==='business'?'':' class="hidden"')+'><label for="bCompany">Bedrijfsnaam</label><input id="bCompany" maxlength="120" value="'+safe(c.billing_company)+'"></div>')+'<div class="row"><div><label for="bContact">Contactpersoon</label><input id="bContact" maxlength="120" value="'+safe(c.contact_name)+'"></div><div><label for="bInvoiceEmail">Factuur-e-mail (optioneel)</label><input id="bInvoiceEmail" type="email" maxlength="254" value="'+safe(c.invoice_email)+'"></div></div><label for="bStreet">Straat en huisnummer</label><input id="bStreet" maxlength="160" value="'+safe(c.street)+'" autocomplete="street-address"><div class="row"><div><label for="bPostal">Postcode</label><input id="bPostal" maxlength="12" value="'+safe(c.postal_code)+'" autocomplete="postal-code"></div><div><label for="bCity">Plaats</label><input id="bCity" maxlength="80" value="'+safe(c.city)+'" autocomplete="address-level2"></div></div><label for="bCountry">Land</label><input id="bCountry" maxlength="60" value="'+safe(c.country||'Nederland')+'" autocomplete="country-name"><div data-business-only'+(company||context==='business'?'':' class="hidden"')+'><div class="row"><div><label for="bVat">Btw-nummer (optioneel)</label><input id="bVat" maxlength="30" value="'+safe(c.vat_number)+'" placeholder="NL123456789B01"></div><div><label for="bKvk">KvK-nummer (optioneel)</label><input id="bKvk" maxlength="8" inputmode="numeric" value="'+safe(c.kvk_number)+'"></div></div></div>'}
function readBilling(){const v=id=>($(id)?$(id).value.trim():'');return {billing_company:v('bCompany'),contact_name:v('bContact'),invoice_email:v('bInvoiceEmail'),street:v('bStreet'),postal_code:v('bPostal'),city:v('bCity'),country:v('bCountry'),vat_number:v('bVat'),kvk_number:v('bKvk')}}
function renderAccount(){const admin=me.role==='admin';if(!shop){$('accountBody').innerHTML='<p class="muted">Gebruikersnaam: '+safe(me.username)+'</p>';return}const c=shop.customer,a=shop.account;
  let h='<div class="grid" style="margin-bottom:12px"><div class="stat"><strong style="font-size:16px">'+safe(a.name||a.email)+'</strong><span>'+safe(a.email)+'</span></div><div class="stat"><strong style="font-size:16px">'+safe(c.customer_type==='business'?'Organisatie':'Particulier / zelfstandig')+'</strong><span>Klantnummer '+safe(c.customer_number||'—')+'</span></div><div class="stat"><strong style="font-size:16px">'+(a.role==='admin'?'Beheerder':'Gebruiker')+'</strong><span>Jouw rol</span></div></div>';
  if(admin)h+='<form id="billingForm"><h3>Factuurgegevens</h3>'+billingFields(c,c.billing_company?'business':'private')+'<div class="actions"><button>Opslaan</button></div><div id="billingMessage" role="status"></div></form>';else h+='<p class="muted small">Factuurgegevens worden beheerd door een beheerder van jullie account.</p>';
  $('accountBody').innerHTML=h;const f=$('billingForm');if(f)f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('button');busy(b,true);$('billingMessage').textContent='';try{await api('/api/customer/account/billing',{method:'PATCH',body:JSON.stringify(readBilling())});$('billingMessage').className='notice';$('billingMessage').textContent='Opgeslagen.';await refreshShop()}catch(err){$('billingMessage').className='error';$('billingMessage').textContent=err.message}finally{busy(b,false)}}}

async function loadTeam(){const d=await api('/api/customer/team'),active=d.users.filter(u=>!u.disabled_at).length,limit=d.limit;$('teamHint').textContent='Gebruikers van jullie organisatie: '+active+' van '+(limit===null?'onbeperkt':limit)+'.';
  $('teamBody').innerHTML='<div class="table-wrap"><table style="min-width:520px"><thead><tr><th>Naam</th><th>Rol</th><th>Status</th><th></th></tr></thead><tbody>'+d.users.map(u=>{const self=u.id===shop.account.id;return '<tr><td>'+safe(u.name||u.email)+'<br><span class="muted small">'+safe(u.email)+'</span></td><td>'+(self?'Beheerder (jij)':'<select data-role="'+safe(u.id)+'" aria-label="Rol van '+safe(u.name||u.email)+'"><option value="member"'+(u.role==='member'?' selected':'')+'>Gebruiker</option><option value="admin"'+(u.role==='admin'?' selected':'')+'>Beheerder</option></select>')+'</td><td>'+(u.disabled_at?'Uitgeschakeld':Number(u.active)===1?'Actief':'Uitgenodigd')+'</td><td>'+(self?'':'<button type="button" class="link" data-team="'+(u.disabled_at?'enable':'disable')+'" data-id="'+safe(u.id)+'">'+(u.disabled_at?'Inschakelen':'Uitschakelen')+'</button>')+'</td></tr>'}).join('')+'</tbody></table></div>';
  $('teamForm').classList.toggle('hidden',limit!==null&&active>=limit);if(limit!==null&&active>=limit)$('teamHint').textContent+=' Het maximum van jullie abonnement is bereikt.'}
$('teamBody').onclick=async e=>{const b=e.target.closest('[data-team]');if(!b)return;busy(b,true);try{await api('/api/customer/team/'+b.dataset.id+'/'+b.dataset.team,{method:'POST',body:'{}'});await loadTeam()}catch(err){alert(err.message)}finally{busy(b,false)}};
$('teamBody').onchange=async e=>{const s=e.target.closest('[data-role]');if(!s)return;try{await api('/api/customer/team/'+s.dataset.role+'/role',{method:'POST',body:JSON.stringify({role:s.value})})}catch(err){alert(err.message);await loadTeam()}};
$('teamForm').onsubmit=async e=>{e.preventDefault();busy($('teamButton'),true);$('teamMessage').textContent='';try{await api('/api/customer/team',{method:'POST',body:JSON.stringify({name:$('teamName').value.trim(),email:$('teamEmail').value.trim()})});$('teamForm').reset();$('teamMessage').className='notice';$('teamMessage').textContent='Uitnodiging verstuurd. De link is één uur geldig.';await loadTeam()}catch(err){$('teamMessage').className='error';$('teamMessage').textContent=err.message}finally{busy($('teamButton'),false)}};

async function refreshShop(){shop=await api('/api/customer/shop/summary');renderNotices();renderProducts();renderSubscriptions();renderLicenses();renderBilling()}

async function openCheckout(priceId){setTab('checkout');const box=$('checkoutBody');box.innerHTML='<p class="loading">Bestelling laden…</p>';
  if(me.role!=='admin'){box.innerHTML='<div class="notice warn">Alleen een beheerder van jullie account kan bestellen.</div>';store('cohentra-buy',null);return}
  let d;try{d=await api('/api/customer/shop/prices/'+encodeURIComponent(priceId))}catch(err){box.innerHTML='<div class="notice error">'+safe(err.message)+'</div>';store('cohentra-buy',null);return}
  const c=shop.customer,individual=me.customer_type==='individual',p=d.price,pl=d.plan;
  let h='<div class="item"><div class="item-head"><div><h3>'+safe(d.product.name)+' · '+safe(pl.name)+'</h3><p class="muted small" style="margin:0">'+safe(pl.description||'')+'</p></div><strong style="font-size:20px">'+safe(money(p.unit_amount,p.currency))+' <span class="muted small" style="font-weight:400">'+safe(period(p))+(p.tax_behavior==='inclusive'?', incl. btw':p.tax_behavior==='exclusive'?', excl. btw':'')+'</span></strong></div>'+featureList(pl.features,d.product.features)+'<p class="small muted" style="margin:10px 0 0">'+(pl.max_activations!==null&&pl.max_activations!==undefined?'Tot '+safe(pl.max_activations)+' activaties. ':'')+(pl.max_users?'Tot '+safe(pl.max_users)+' gebruikers. ':'')+(pl.billing_type==='recurring'?'Loopt door tot je opzegt; opzeggen kan per het einde van elke betaalperiode.':'Eenmalige aankoop.')+(pl.trial_days?' Inclusief '+safe(pl.trial_days)+' dagen proefperiode (één keer per klant).':'')+'</p></div>';
  if(!d.checkout_available)h+='<div class="notice warn">Online bestellen is nog niet geopend. <a href="mailto:info@cohentra.digital?subject=Bestelling">Neem contact op</a> voor een offerte.</div>';
  h+='<form id="checkoutForm">'+(individual?'<fieldset style="border:0;padding:0;margin:14px 0 0"><legend style="font-weight:650">Deze aankoop is</legend><div class="choice"><label><input type="radio" name="purchaseContext" value="private" checked><span>Privé</span></label><label><input type="radio" name="purchaseContext" value="business"><span>Zakelijk<small>Bijvoorbeeld voor je eenmanszaak; met bedrijfsnaam en eventueel btw-nummer op de factuur.</small></span></label></div></fieldset>':'')+'<h3 style="margin-top:18px">Factuurgegevens</h3>'+billingFields(c,'private')+'<p class="small muted">Je betaalt in de beveiligde betaalomgeving van Stripe. Je krijgt pas toegang als Stripe de betaling heeft bevestigd.</p><div class="actions"><button id="payButton"'+(d.checkout_available?'':' disabled')+'>Doorgaan naar betalen</button><button type="button" class="secondary" id="checkoutCancel">Annuleren</button></div><div id="checkoutError" class="error" role="alert"></div></form>';
  box.innerHTML=h;
  box.querySelectorAll('input[name=purchaseContext]').forEach(r=>r.onchange=()=>box.querySelectorAll('[data-business-only]').forEach(x=>x.classList.toggle('hidden',r.value!=='business'&&r.checked)));
  $('checkoutCancel').onclick=()=>{store('cohentra-buy',null);setTab('products')};
  $('checkoutForm').onsubmit=async e=>{e.preventDefault();busy($('payButton'),true);$('checkoutError').textContent='';const ctx=box.querySelector('input[name=purchaseContext]:checked');
    try{const r=await api('/api/customer/checkout',{method:'POST',body:JSON.stringify({price_id:priceId,purchase_context:ctx?ctx.value:'business',billing:readBilling()})});store('cohentra-buy',null);location.href=r.url}
    catch(err){$('checkoutError').textContent=err.message;if(err.code==='subscription_exists'||err.code==='already_owned')store('cohentra-buy',null);busy($('payButton'),false)}}}

async function showReturn(){setTab('return');const box=$('returnBody'),orderId=params.get('order');history.replaceState({},'',location.pathname);
  if(params.get('checkout')==='cancel'){box.innerHTML='<div class="notice info">Je hebt het betalen afgebroken. Er is niets afgeschreven. Je kunt het later opnieuw proberen via de shop.</div>';return}
  box.innerHTML='<div class="notice info">Bedankt! We wachten op de bevestiging van je betaling door Stripe. Dit duurt meestal enkele seconden…</div>';
  for(let i=0;i<30;i++){let d;try{d=await api('/api/customer/orders/'+encodeURIComponent(orderId)+(i>=5&&i%5===0?'?refresh=1':''))}catch(err){box.innerHTML='<div class="notice error">'+safe(err.message)+'</div>';return}
    const o=d.order;if(o.status==='paid'){box.innerHTML='<div class="notice">Betaling bevestigd voor '+safe(o.product_name+' · '+(o.plan_name||''))+' (bestelling '+safe(o.order_number)+'). Je product staat klaar onder Mijn producten.</div><div class="actions"><button type="button" data-tab="products">Naar mijn producten</button><button type="button" class="secondary" data-tab="licenses">Licentie aanmaken</button></div>';box.onclick=e=>{const t=e.target.closest('[data-tab]');if(t)setTab(t.dataset.tab)};await refreshShop();return}
    if(o.status==='failed'||o.status==='expired'){box.innerHTML='<div class="notice error">De betaling voor bestelling '+safe(o.order_number)+' is niet gelukt. Er is niets afgeschreven en je hebt nog geen toegang. Probeer het opnieuw via de shop.</div>';return}
    await new Promise(r=>setTimeout(r,2000))}
  box.innerHTML='<div class="notice warn">De betaling is nog niet bevestigd. Sommige betaalmethoden hebben meer tijd nodig. Je krijgt automatisch toegang zodra Stripe de betaling bevestigt; kijk later nog eens onder Mijn producten.</div>'}

// ---- Bestaande onderdelen: EventHub-licentiequotum, support, wachtwoord ----
function dateToday(){return new Date().toISOString().slice(0,10)}
async function loadLegacy(){const list=await api('/api/customer/licenses');$('legacyBox').classList.remove('hidden');$('used').textContent=me.licenses_in_use;$('limit').textContent=me.max_licenses;$('types').textContent=me.allowed_license_types.map(x=>x==='admin'?'Beheerder':'Gesloten beta').join(', ');$('createForm').classList.toggle('hidden',me.role!=='admin');$('type').innerHTML=me.allowed_license_types.map(x=>'<option value="'+safe(x)+'">'+(x==='admin'?'Beheerder':'Gesloten beta')+'</option>').join('');$('dates').classList.toggle('hidden',$('type').value==='admin');$('validFrom').value=dateToday();$('validUntil').value=dateToday();$('licenses').innerHTML=list.licenses.length?list.licenses.map(x=>'<tr><td>'+safe(x.label||'—')+'</td><td>'+safe(x.license_type)+'</td><td>'+safe(x.valid_from)+'</td><td>'+safe(x.valid_until)+'</td><td>'+safe(x.status)+'</td><td>'+(x.revoked_at||me.role!=='admin'?'':'<button class="danger" data-revoke="'+safe(x.id)+'">Intrekken</button>')+'</td></tr>').join(''):'<tr><td colspan="6" class="muted">Er zijn nog geen licenties.</td></tr>'}
async function loadTickets(){const d=await api('/api/customer/tickets');$('myTickets').innerHTML=d.tickets.length?d.tickets.map(t=>'<tr><td><strong>'+safe(t.reference)+'</strong></td><td>'+safe(t.subject)+'</td><td>'+safe(new Date(t.created_at).toLocaleString('nl-NL'))+'</td><td>'+safe(ticketStatusLabel(t.status))+'</td></tr>').join(''):'<tr><td colspan="4" class="muted">Je hebt nog geen supportaanvragen.</td></tr>'}
function ticketStatusLabel(s){return ({new:'Nieuw',in_progress:'In behandeling',waiting_customer:'Wacht op jou',closed:'Afgerond'})[s]||s}
$('type').onchange=()=>{$('dates').classList.toggle('hidden',$('type').value==='admin')};
$('createForm').onsubmit=async e=>{e.preventDefault();$('createError').textContent='';$('createdKey').classList.add('hidden');busy($('createButton'),true);try{const d=await api('/api/customer/licenses',{method:'POST',body:JSON.stringify({label:$('label').value.trim(),license_type:$('type').value,valid_from:$('validFrom').value,valid_until:$('validUntil').value})});$('keyValue').textContent=d.license.license_key;$('createdKey').classList.remove('hidden');$('copyKey').onclick=()=>navigator.clipboard.writeText(d.license.license_key);$('label').value='';me=(await api('/api/customer/me')).customer;await loadLegacy()}catch(err){$('createError').textContent=err.message}finally{busy($('createButton'),false)}};
$('licenses').onclick=async e=>{const id=e.target.dataset.revoke;if(!id)return;if(!confirm('Deze licentie intrekken? De licentie kan daarna niet meer worden gebruikt.'))return;e.target.disabled=true;try{await api('/api/customer/licenses/'+encodeURIComponent(id)+'/revoke',{method:'POST',body:'{}'});me=(await api('/api/customer/me')).customer;await loadLegacy()}catch(err){alert(err.message)}finally{e.target.disabled=false}};
$('ticketForm').onsubmit=async e=>{e.preventDefault();$('ticketError').textContent='';$('ticketCreated').classList.add('hidden');busy($('ticketButton'),true);try{const d=await api('/api/customer/tickets',{method:'POST',body:JSON.stringify({category:$('ticketCategory').value,subject:$('ticketSubject').value.trim(),message:$('ticketMessage').value.trim()})});$('ticketCreated').innerHTML='Je supportaanvraag is aangemaakt. Bewaar je referentienummer: <strong class="key">'+safe(d.reference)+'</strong>. Je kunt de status hieronder volgen.'+(d.email_sent?' Een melding is ook naar Cohentra Support verstuurd.':' De e-mailmelding kon niet worden verstuurd; je aanvraag staat wel in het portaal. Vermeld het referentienummer als je contact opneemt via support@cohentra.digital.');$('ticketCreated').classList.remove('hidden');$('ticketForm').reset();await loadTickets()}catch(err){$('ticketError').textContent=err.message}finally{busy($('ticketButton'),false)}};
$('passwordForm').onsubmit=async e=>{e.preventDefault();$('passwordMessage').textContent='';try{const d=await api('/api/customer/account/password',{method:'POST',body:JSON.stringify({old_password:$('oldPassword').value,new_password:$('newPassword').value})});token=d.session_token;sessionStorage.setItem('cohentra-customer-token',token);$('passwordForm').reset();$('passwordMessage').textContent='Wachtwoord gewijzigd.'}catch(err){$('passwordMessage').textContent=err.message}};

// ---- Aanmelden, registreren, herstellen ----
$('loginForm').onsubmit=async e=>{e.preventDefault();busy($('loginButton'),true);$('loginError').textContent='';try{const d=await publicPost('/api/customer/auth/login',{username:$('username').value.trim(),password:$('password').value});token=d.session_token;sessionStorage.setItem('cohentra-customer-token',token);await load()}catch(err){$('loginError').textContent=err.message}finally{busy($('loginButton'),false)}};
$('toRegister').onclick=()=>{showPanel('registerPanel');$('regName').focus()};$('registerBack').onclick=()=>showPanel('login');
document.querySelectorAll('input[name=customerType]').forEach(r=>r.onchange=()=>$('companyBox').classList.toggle('hidden',document.querySelector('input[name=customerType]:checked').value!=='business'));
$('registerForm').onsubmit=async e=>{e.preventDefault();const m=$('registerMessage');m.textContent='';m.className='';const type=document.querySelector('input[name=customerType]:checked').value;
  if($('regPassword').value.length<10){m.className='error';m.textContent='Gebruik een wachtwoord van minimaal 10 tekens.';return}
  busy($('registerButton'),true);try{const d=await publicPost('/api/customer/auth/register',{customer_type:type,name:$('regName').value.trim(),company_name:$('regCompany').value.trim(),email:$('regEmail').value.trim(),password:$('regPassword').value});m.className='notice';m.textContent=d.message;$('registerForm').querySelectorAll('input').forEach(i=>{if(i.type!=='radio')i.value=''})}catch(err){m.className='error';m.textContent=err.message}finally{busy($('registerButton'),false)}};
$('forgotButton').onclick=()=>{showPanel('forgotPanel');$('forgotEmail').value=$('username').value.includes('@')?$('username').value:'';$('forgotEmail').focus()};
$('backToLogin').onclick=()=>showPanel('login');$('verifyToLogin').onclick=()=>showPanel('login');
$('forgotForm').onsubmit=async e=>{e.preventDefault();busy($('forgotSubmit'),true);$('forgotMessage').textContent='';try{const d=await publicPost('/api/customer/auth/forgot-password',{email:$('forgotEmail').value.trim()});$('forgotMessage').textContent=d.message;$('forgotMessage').className='notice'}catch(err){$('forgotMessage').textContent=err.message;$('forgotMessage').className='error'}finally{busy($('forgotSubmit'),false)}};
$('tokenForm').onsubmit=async e=>{e.preventDefault();busy($('tokenSubmit'),true);$('tokenMessage').textContent='';try{if($('tokenPassword').value!==$('tokenPasswordConfirm').value)throw Error('De wachtwoorden komen niet overeen.');await publicPost('/api/customer/auth/complete-email-auth',{token:params.get('token'),flow:params.get('flow'),password:$('tokenPassword').value});history.replaceState({},'',location.pathname);showPanel('login');$('loginError').textContent='Je wachtwoord is ingesteld. Je kunt nu aanmelden.'}catch(err){$('tokenMessage').textContent=err.message}finally{busy($('tokenSubmit'),false)}};
$('logout').onclick=async()=>{try{await api('/api/customer/auth/logout',{method:'POST',body:'{}'})}catch{}token='';sessionStorage.removeItem('cohentra-customer-token');showPanel('login')};

async function verifyEmail(){showPanel('verifyPanel');const t=params.get('token');history.replaceState({},'',location.pathname);try{const d=await publicPost('/api/customer/auth/verify-email',{token:t});token=d.session_token;sessionStorage.setItem('cohentra-customer-token',token);await load()}catch(err){$('verifyMessage').textContent=err.message;$('verifyActions').classList.remove('hidden')}}

if(params.get('buy')&&/^[0-9a-f-]{36}$/.test(params.get('buy'))){store('cohentra-buy',params.get('buy'));history.replaceState({},'',location.pathname)}
if(params.get('token')&&params.get('flow')==='verify')verifyEmail();
else if(params.get('token')&&['invite','reset'].includes(params.get('flow'))){showPanel('tokenPanel');if(params.get('flow')==='reset')$('tokenTitle').textContent='Nieuw wachtwoord kiezen'}
else if(token)load().catch(e=>{showPanel('login');$('loginError').textContent=e.message});
else{showPanel('login');if(stored('cohentra-buy')&&params.get('register')==='1')$('toRegister').click()}
</script></body></html>`;
